function arcPts(a,b,bend){const dy=b[0]-a[0],dx=b[1]-a[1],c=[(a[0]+b[0])/2-dx*bend,(a[1]+b[1])/2+dy*bend],o=[];for(let i=0;i<=24;i++){const t=i/24,u=1-t;o.push([u*u*a[0]+2*u*t*c[0]+t*t*b[0],u*u*a[1]+2*u*t*c[1]+t*t*b[1]]);}return o;}
