function hm(m){if(!Number.isFinite(m))return '';m=Math.round(m);return m<60?m+' min':Math.floor(m/60)+' h'+(m%60?' '+String(m%60).padStart(2,'0'):'');}
function med(a){const v=a.filter(Number.isFinite).sort((x,y)=>x-y);return v.length?v[Math.floor((v.length-1)/2)]:NaN;}
function polyDec(s){let i=0,la=0,lo=0;const o=[];while(i<s.length){for(let k=0;k<2;k++){let b,sh=0,r=0;do{b=s.charCodeAt(i++)-63;r|=(b&31)<<sh;sh+=5;}while(b>=32&&i<s.length);const d=r&1?~(r>>1):r>>1;if(k)lo+=d;else la+=d;}o.push([la/1e5,lo/1e5]);}return o;}
