async function flows(){const host=$('#flow-results')||$('#chain-flows');if(!host||!record)return;try{const data=await D.movements(code);if(!data||data.missing){host.innerHTML='<p>'+T('missing')+'</p>';return;}host.innerHTML=line('Para transportar gado, é obrigatório emitir uma '+term('GTA','permit')+'.','By law, moving cattle needs a '+term('transit permit','permit')+' (GTA).')+line('Em '+esc(data.year)+', as guias registraram '+P.large(data.outgoing,lang)+' saídas de gado do município.','In '+esc(data.year)+', permits recorded '+P.large(data.outgoing,lang)+' head of cattle leaving the municipality.')+'<p class="period">'+esc(data.source.name)+' · '+esc(data.period?.[lang]||data.year)+'</p>'+line('O mesmo animal pode aparecer em mais de uma guia.','The same animal can show up on more than one permit.');const routes=await D.routes(code,data.year);if(routes)for(const dir of ['incoming','outgoing']){const top=routes[dir].slice(0,3);host.innerHTML+='<h3>'+tr(dir==='incoming'?'De onde mais chega gado':'Para onde mais sai gado',dir==='incoming'?'Where most cattle come from':'Where most cattle go')+'</h3>'+(top.length?top.map(r=>'<p class="route-label">'+esc(r.name)+' · '+P.large(r.heads,lang)+'</p><div class="route-bar" role="img" aria-label="'+esc(r.name+' '+P.large(r.heads,lang))+'"><span style="width:'+Math.max(1,100*r.heads/top[0].heads)+'%"></span></div>').join(''):'<p>'+T('missing')+'</p>');}}catch{host.innerHTML='<p>'+T('missing')+'</p>';}finally{host.dataset.flowReady='true';}}
